using System.Collections.Generic;
using Mirror;using MultiFPS;using MultiFPS.UI;using UnityEngine;using UnityEngine.UI;using UnityEngine.InputSystem;using UnityEngine.SceneManagement;using ROM.Horde;using ROM.UI.Sprint01;
namespace ROM.UI.Gameplay {
[DefaultExecutionOrder(950)]
public sealed class RiftFieldUI:MonoBehaviour {
 public RiftHUDTheme Theme;public RectTransform MapPanel,Content,Viewport,PlayerMarker,PotionRoot;public RawImage MapImage;public Text MapInfo;public Button CloseButton,MapButton;public Button[] Potions;public Text[] Counts,Keys,Timers;public Image[] Cooldowns;
 public bool MapOpen=>MapPanel&&MapPanel.gameObject.activeSelf;
 RiftMinimapAtlas atlas;bool cursorHeld,pauseAllowed;float next;readonly List<Transform> pins=new List<Transform>();Canvas canvas;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Install(){SceneManager.sceneLoaded-=Loaded;SceneManager.sceneLoaded+=Loaded;}
 static void Loaded(Scene scene,LoadSceneMode mode){if(scene.name=="map_rom_horde"&&!FindFirstObjectByType<RiftFieldUI>()){var prefab=Resources.Load<GameObject>("RiftFieldUI");if(prefab)Instantiate(prefab);}}
 void Awake(){canvas=GetComponent<Canvas>();if(!MapPanel)Build();atlas=Resources.Load<RiftMinimapAtlas>("RiftMinimapAtlas");if(atlas)MapImage.texture=atlas.Map;CloseButton.onClick.AddListener(()=>SetMap(false));MapButton.onClick.AddListener(()=>SetMap(!MapOpen));for(int i=0;i<2;i++){int id=i;Potions[i].onClick.AddListener(()=>Drink(id));}MapPanel.gameObject.SetActive(false);}
 void Update(){var player=ClientFrontend.ClientPlayerInstance;var actor=player?player.MyCharacter:null;bool valid=actor&&actor.Health.CurrentHealth>0&&!ClientFrontend.Hub;
  canvas.enabled=valid;if(!valid||ClientFrontend.Pause){if(MapOpen)SetMap(false);return;}
  if(MapOpen){if(RiftControls.Pressed("WorldMap")||RiftControls.Pressed("Pause")){RiftControls.EscapeConsumedFrame=Time.frameCount;SetMap(false);return;}if(Mouse.current!=null&&RectTransformUtility.RectangleContainsScreenPoint(Viewport,Mouse.current.position.ReadValue())){float scroll=Mouse.current.scroll.ReadValue().y;if(scroll!=0)SetZoom(Content.localScale.x*(scroll>0?1.15f:.87f));}PlayerMarker.anchoredPosition=Position(actor.transform.position);PlayerMarker.localRotation=Quaternion.Euler(0,0,-actor.Input.LookY);}
  else if(UICursorManager.GamePlayInput()&&!RiftControls.Rebinding){if(RiftControls.Pressed("WorldMap"))SetMap(true);if(RiftControls.Pressed("Potion"))Drink(0);else if(RiftControls.Pressed("PotionMajor"))Drink(1);}
  PotionRoot.gameObject.SetActive(!MapOpen);if(Time.unscaledTime<next)return;next=Time.unscaledTime+.1f;MapButton.GetComponentInChildren<Text>().text="MAPA ["+RiftControls.Label("WorldMap")+"]";var village=player.GetComponent<RiftVillagePlayer>();double remain=village?System.Math.Max(0,village.PotionReadyAt-NetworkTime.time):0;
  for(int i=0;i<2;i++){int count=RiftVillageSupplies.Count(i);Counts[i].text=count.ToString();Keys[i].text=RiftControls.Label(i==0?"Potion":"PotionMajor");Keys[i].fontSize=Keys[i].text.Length>4?10:12;Timers[i].text=remain>0?remain.ToString("0.0"):"";Cooldowns[i].fillAmount=(float)remain/5;Potions[i].interactable=count>0&&remain<=0&&actor.Health.CurrentHealth<actor.Health.MaxHealth;}
 }
 public void Drink(int id){var player=ClientFrontend.ClientPlayerInstance;if(player&&UICursorManager.GamePlayInput()&&!ClientFrontend.Pause&&!MapOpen)player.GetComponent<RiftVillagePlayer>().CmdDrinkPotion(id);}
 public void SetMap(bool open){if(open==MapOpen)return;if(open){if(!atlas||!atlas.Map)return;MapPanel.gameObject.SetActive(true);pauseAllowed=UIPauseMenu._instance?UIPauseMenu._instance.AbleToPause:true;if(UIPauseMenu._instance)UIPauseMenu._instance.AbleToPause=false;UICursorManager.RequestCursor(gameObject);cursorHeld=true;SetZoom(1);Content.anchoredPosition=Vector2.zero;Pins();PlayerMarker.SetAsLastSibling();MapInfo.text="EL RIFT · Cristales y refugios: azul · Encuentros: rojo · Tu posición: dorado. Rueda: zoom · Arrastrar: mover.";}else{MapPanel.gameObject.SetActive(false);if(cursorHeld){UICursorManager.ReleaseCursor(gameObject);cursorHeld=false;if(UIPauseMenu._instance)UIPauseMenu._instance.AbleToPause=pauseAllowed;}}RiftAbilityTooltip.HideAll();}
 public void SetZoom(float scale){scale=Mathf.Clamp(scale,1,4);Content.localScale=Vector3.one*scale;PlayerMarker.localScale=Vector3.one/scale;foreach(var pin in pins)if(pin)pin.localScale=Vector3.one/scale;}
 public Vector2 Position(Vector3 world)=>atlas?new Vector2((world.x-atlas.Center.x)/atlas.WorldSize.x*Content.rect.width,(world.z-atlas.Center.y)/atlas.WorldSize.y*Content.rect.height):Vector2.zero;
 void Pins(){foreach(var pin in pins)if(pin)Destroy(pin.gameObject);pins.Clear();var world=ROM.Horde.Horde.Instance;if(!world)return;foreach(var crystal in world.Checkpoints)if(crystal)Pin(crystal.Title,crystal.transform.position,new Color(.25f,.7f,1),true);foreach(var encounter in world.Encounters)if(encounter)Pin(encounter.Title,encounter.transform.position,new Color(1,.18f,.12f),false);}
 void Pin(string title,Vector3 position,Color color,bool label){var pin=Rect(Content,title,new Vector2(.5f,.5f),Position(position),new Vector2(14,14));var graphic=pin.gameObject.AddComponent<RiftHUDGraphic>();graphic.Shape=HUDShape.Diamond;graphic.color=color;graphic.raycastTarget=true;var button=pin.gameObject.AddComponent<Button>();button.targetGraphic=graphic;button.onClick.AddListener(()=>MapInfo.text=title+" · X: "+position.x.ToString("0")+"  Y: "+position.z.ToString("0"));var tip=pin.gameObject.AddComponent<RiftTooltipTrigger>();tip.Title=title;tip.Description=label?"Cristal / refugio":"Zona de encuentro";if(label)Label(pin,title,new Vector2(0,-17-(pins.Count%3)*14),new Vector2(180,24),11);pins.Add(pin);}
 void OnDisable(){if(cursorHeld)SetMap(false);}
 RectTransform Rect(Transform parent,string name,Vector2 anchor,Vector2 pos,Vector2 size){var rect=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();rect.SetParent(parent,false);rect.anchorMin=rect.anchorMax=anchor;rect.pivot=new Vector2(.5f,.5f);rect.anchoredPosition=pos;rect.sizeDelta=size;return rect;}
 Text Label(Transform parent,string text,Vector2 pos,Vector2 size,int font){var rect=Rect(parent,text,new Vector2(.5f,.5f),pos,size);var label=rect.gameObject.AddComponent<Text>();label.font=Theme.BodyFont;label.text=text;label.fontSize=font;label.alignment=TextAnchor.MiddleCenter;label.color=Theme.Text;label.raycastTarget=false;return label;}
 Button Button(Transform parent,string name,Vector2 anchor,Vector2 pos,Vector2 size){var rect=Rect(parent,name,anchor,pos,size);var image=rect.gameObject.AddComponent<RiftHUDGraphic>();image.Shape=HUDShape.Slot;image.color=Color.white;image.Bottom=new Color(.008f,.008f,.014f,.96f);image.Border=Theme.Gold;image.raycastTarget=true;var b=rect.gameObject.AddComponent<Button>();b.targetGraphic=image;return b;}
 public void Build(){if(!Theme)Theme=Resources.Load<RiftHUDTheme>("RiftHUDTheme");canvas=GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=145;var scaler=GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1448,1086);scaler.matchWidthOrHeight=1;
  MapButton=Button(transform,"Open world map",new Vector2(1,1),new Vector2(-145,-277),new Vector2(110,23));Label(MapButton.transform,"MAPA [M]",Vector2.zero,new Vector2(108,23),12);
  MapPanel=Rect(transform,"El Rift full map",new Vector2(.5f,.5f),Vector2.zero,new Vector2(1300,940));var panel=MapPanel.gameObject.AddComponent<RiftHUDGraphic>();panel.Shape=HUDShape.Panel;panel.color=Color.white;panel.Bottom=new Color(.008f,.01f,.018f,.98f);panel.Border=Theme.Gold;panel.raycastTarget=true;Label(MapPanel,"EL RIFT",new Vector2(0,425),new Vector2(800,40),26);CloseButton=Button(MapPanel,"Close world map",new Vector2(1,1),new Vector2(-40,-35),new Vector2(40,35));Label(CloseButton.transform,"×",Vector2.zero,new Vector2(40,35),24);
  Viewport=Rect(MapPanel,"Map viewport",new Vector2(.5f,.5f),new Vector2(0,0),new Vector2(1200,760));Viewport.gameObject.AddComponent<RectMask2D>();var scroll=Viewport.gameObject.AddComponent<ScrollRect>();scroll.viewport=Viewport;scroll.horizontal=scroll.vertical=true;scroll.scrollSensitivity=0;scroll.movementType=ScrollRect.MovementType.Clamped;Content=Rect(Viewport,"Map content",new Vector2(.5f,.5f),Vector2.zero,new Vector2(740,740));MapImage=Content.gameObject.AddComponent<RawImage>();MapImage.raycastTarget=true;scroll.content=Content;PlayerMarker=Rect(Content,"Your position",new Vector2(.5f,.5f),Vector2.zero,new Vector2(18,22));var arrow=PlayerMarker.gameObject.AddComponent<RiftHUDGraphic>();arrow.Shape=HUDShape.Arrow;arrow.color=Theme.BrightGold;arrow.raycastTarget=false;MapInfo=Label(MapPanel,"",new Vector2(0,-420),new Vector2(1200,60),16);
  PotionRoot=Rect(transform,"Compact potions",new Vector2(.5f,0),new Vector2(0,115),new Vector2(800,75));Potions=new Button[2];Counts=new Text[2];Keys=new Text[2];Timers=new Text[2];Cooldowns=new Image[2];for(int i=0;i<2;i++){var button=Potions[i]=Button(PotionRoot,"Potion "+i,new Vector2(.5f,.5f),new Vector2(i==0?-280:346,0),new Vector2(44,46));var icon=Rect(button.transform,"Potion bottle",new Vector2(.5f,.5f),Vector2.zero,new Vector2(30,36)).gameObject.AddComponent<RiftHUDGraphic>();icon.Shape=HUDShape.Potion;icon.color=i==0?new Color(.9f,.04f,.12f):new Color(1,.25f,.5f);icon.Border=Theme.Gold;icon.raycastTarget=false;var cooldown=Rect(button.transform,"Shared cooldown",new Vector2(.5f,.5f),Vector2.zero,new Vector2(44,46)).gameObject.AddComponent<Image>();cooldown.sprite=Theme.White;cooldown.type=Image.Type.Filled;cooldown.fillMethod=Image.FillMethod.Radial360;cooldown.color=new Color(0,0,0,.75f);cooldown.fillAmount=0;cooldown.raycastTarget=false;Cooldowns[i]=cooldown;Counts[i]=Label(button.transform,"0",new Vector2(14,-15),new Vector2(24,20),12);Keys[i]=Label(button.transform,"",new Vector2(0,-35),new Vector2(90,20),12);Timers[i]=Label(button.transform,"",Vector2.zero,new Vector2(44,28),15);var tip=button.gameObject.AddComponent<RiftTooltipTrigger>();tip.Title=RiftVillageSupplies.Name(i);tip.Description="Recupera "+(RiftVillageSupplies.Healing(i)*100).ToString("0")+"% de vida.\nRecarga compartida: 5 s.\nCantidad: inventario de provisiones.\nAtajo reasignable en Controles.";tip.ActionId=i==0?"Potion":"PotionMajor";}
  MapPanel.gameObject.SetActive(false);
 }
}
}
